('sergiopaniego-trl-openenv-harness-training', 'Training a coding agent using the OpenCode harness in remote HF sandboxes with TRL and OpenEnv', 'Sergio Paniego shows how to train a coding agent with the OpenCode harness in remote Hugging Face sandboxes, combining TRL and OpenEnv for reproducible agent training workflows.', 'Sergio Paniego', 'https://www.google.com/s2/favicons?domain=huggingface.co&sz=128', 'AI Agents', array['Coding Agents','TRL','OpenEnv','Reinforcement Learning'], '10 min read', '2026-08-10', 'Hugging Face Blog', 'https://huggingface.co/blog/sergiopaniego/trl-openenv-harness-training', 'https://cdn-uploads.huggingface.co/production/uploads/61929226ded356549e20c5da/hga6XiKt3ZpORxp6W6WTj.jpeg', 'OpenCode harness training article cover', 'cover', 'published', false),
('liquidai-lfm2-5-2-6b', 'Deploy local agents everywhere with LFM2.5-2.6B', 'Liquid AI introduces LFM2.5-2.6B, a compact multimodal language model designed to bring capable local agents to more devices and deployment environments.', 'Liquid AI', 'https://www.google.com/s2/favicons?domain=huggingface.co&sz=128', 'Foundation Model', array['LFM2.5','Small Language Models','Local AI','Agents'], '8 min read', '2026-08-10', 'Hugging Face Blog', 'https://huggingface.co/blog/LiquidAI/lfm2-5-2-6b', 'https://cdn-uploads.huggingface.co/production/uploads/644249b08443bce4c9890a0f/DsoMk3kqhMYedjPiZINKv.png', 'LFM2.5-2.6B article cover', 'cover', 'published', false),
('jinaai-jina-reranker-v3-5-faster-listwise-reranking', 'jina-reranker-v3.5: Faster Listwise Reranking with Hybrid Attention and Self-Distillation', 'Jina AI presents jina-reranker-v3.5, improving listwise retrieval reranking speed and quality with hybrid attention and self-distillation.', 'Jina AI', 'https://www.google.com/s2/favicons?domain=huggingface.co&sz=128', 'Efficient AI', array['Reranking','Information Retrieval','Hybrid Attention','Distillation'], '9 min read', '2026-08-10', 'Hugging Face Blog', 'https://huggingface.co/blog/jinaai/jina-reranker-v3-5-faster-listwise-reranking', 'https://cdn-uploads.huggingface.co/production/uploads/642bfcfaeffb25812edf2864/BVebsaREJxM68yxdMFv3G.png', 'jina-reranker-v3.5 article cover', 'cover', 'published', false),
('lightonai-mdenseon-mlateon', 'mDenseOn with the mLateOn: Open Multilingual, Long-Context, and Code Retrieval Models', 'LightOn AI releases mDenseOn and mLateOn, open multilingual retrieval models built for long-context and code search across dense and late-interaction architectures.', 'LightOn AI', 'https://www.google.com/s2/favicons?domain=huggingface.co&sz=128', 'Efficient AI', array['Retrieval','Multilingual Models','Long Context','Code Search'], '10 min read', '2026-08-10', 'Hugging Face Blog', 'https://huggingface.co/blog/lightonai/mdenseon-mlateon', 'https://cdn-thumbnails.huggingface.co/social-thumbnails/blog/lightonai/mdenseon-mlateon.png', 'mDenseOn and mLateOn article cover', 'cover', 'published', false)
